/* H5 任务页：赛段倒计时 + 排名制晋级。 */
(function(){
  const previousGo=window.h5Go;
  const tabs=()=>`<nav class="h5-tabbar"><button data-tab="discover" onclick="h5Go('discover')"><span>✦</span>发现</button><button data-tab="notice" onclick="h5Go('notice')"><span>▤</span>须知</button><button data-tab="tasks" onclick="h5Go('tasks')"><span>✓</span>任务</button><button data-tab="rankboard" onclick="h5Go('rankboard')"><span>♛</span>积分榜</button><button data-tab="mine" onclick="h5Go('mine')"><span>◉</span>我的</button></nav>`;
  const top=(title,sub)=>`<div class="h5-top"><div class="h5-status"><span>9:41</span><span>● ● ● ▰</span></div><div class="h5-titlebar"><h1>${title}</h1><i>千铝工投⌄</i></div><p class="h5-sub">${sub}</p></div>`;
  const heading=(title,more='')=>`<div class="section-head"><b>${title}</b><a>${more}</a></div>`;
  const taskCard=(icon,title,state,stateClass,desc,score,progress,label,action)=>`<div class="task-card"><div class="task-icon">${icon}</div><div><b>${title}</b><span class="task-state ${stateClass}">${state}</span><p>${desc}</p><small>今日可得：+${score} 分 · ${progress}</small></div><button class="task-action" onclick="${action}">${label}</button></div>`;
  function discover(){return `${top('发现','2026 年岗位技能竞赛 · 初赛阶段')}<div class="discover-hero"><div class="hero-copy"><small>当前赛段：初赛阶段 · 考试状态：进行中</small><h2>和岗位高手一起，冲刺复赛晋级名额</h2><p>今日任务 2 / 4 · 当前积分 1,280 · 当前排名第 68 名</p><button class="hero-go" onclick="h5Go('tasks')">去完成任务 →</button></div><div class="mascot"><span class="bubble">冲进前 50！</span><i class="helmet"></i><i class="face"></i><i class="body"></i><b class="badge">★</b></div><div class="hero-stats"><div><small>当前积分</small><b>1,280</b></div><div><small>当前排名</small><b>第 68 名</b></div><div><small>晋级线</small><b>第 50 名</b></div></div><div class="hero-stats" style="grid-template-columns:1fr 1fr"><div><small>距离初赛结束</small><b>03 天 12 小时</b></div><div><small>状态提示</small><b>继续完成任务，冲刺复赛名额</b></div></div></div><div class="h5-content">${heading('竞赛风采精选','查看全部')}<article class="feature-card"><div class="feature-cover">电解一车间安全练兵现场</div><div class="feature-info"><b>练在岗位上，比在实战中</b><div class="feature-meta"><span>张建国 · 千铝工投</span><span>♥ 128 <em class="pass-tag">审核通过</em></span></div></div></article><article class="feature-card"><div class="feature-cover orange">班组学习挑战赛火热进行</div><div class="feature-info"><b>一分钟看懂初赛阶段怎么冲分</b><div class="feature-meta"><span>培训管理部 · 06-22</span><span>♥ 96 <em class="pass-tag">审核通过</em></span></div></div></article>${heading('经验分享','更多')}<div class="share-item"><div class="share-thumb"></div><div><b>我的安全生产答题复盘法</b><p>先按类别整理错题，再用 15 分钟做一次限时挑战。</p><span class="share-meta">李雯 · 动力保障部 · 2 小时前 · ♥ 68</span></div></div></div><button class="floating-share" onclick="h5Go('shareCreate')">＋ 发布心得</button>${tabs()}`}
  function tasks(){return `${top('任务','完成任务可继续累计积分，提升初赛排名')}<div class="h5-content"><section class="rank-promotion-card"><div class="status-top"><span>当前赛段：初赛阶段</span><span>● 进行中</span></div><h2>距离初赛结束：03 天 12 小时 28 分钟</h2><p>初赛进行中，系统将在倒计时结束后按个人积分排名自动生成复赛候选名单。</p><div class="rank-rule">晋级规则：初赛结束后按个人积分排名，前 50 名晋级复赛</div><div class="rank-kpis"><div><small>我的当前排名</small><b>第 68 名</b></div><div><small>晋级线</small><b>第 50 名</b></div><div><small>距离晋级线</small><b>还差 18 名</b></div></div><div class="rank-kpis"><div><small>当前积分</small><b>1,280 分</b></div><div><small>赛段状态</small><b>进行中</b></div><div><small>排名口径</small><b>个人积分榜</b></div></div><button class="hero-go" onclick="document.getElementById('todayTasks').scrollIntoView()">去完成今日任务</button></section>${heading('赛段任务')}<div class="stage-switch"><button class="active"><b>初赛任务</b>进行中</button><button class="disabled" onclick="showToast('当前赛段暂未开启，请等待晋级结果公布。')"><b>🔒 复赛任务</b><span>未开启</span></button><button class="disabled" onclick="showToast('当前赛段暂未开启，请等待晋级结果公布。')"><b>🔒 决赛任务</b><span>未开启</span></button></div><div id="todayTasks">${heading('今日任务')}<p class="task-section-sub">完成今日任务可继续累计积分，提升初赛排名。</p><div class="task-list">${taskCard('☀','每日签到','未完成','', '每日签到可获得基础积分','5','累计 6 天',"去签到","openSign()")}${taskCard('▸','在线学习','进行中','doing','完成指定课程学习并通过学后答题','20','1 / 2 门课程',"继续学习","h5Go('study')")}${taskCard('？','学后答题','待完成','', '完成课程后答题，正确率达标可获得积分','10','0 / 1 次',"去答题","h5Go('studyQuiz')")}${taskCard('⚡','答题闯关','进行中','doing','完成当前赛段闯关任务，提高个人积分排名','30','2 / 3 个关卡',"开始闯关","h5Go('gate')")}</div></div>${heading('当前初赛任务详情')}<div class="stage-task-detail"><b>初赛阶段 · 积分排名赛</b><p>任务积分会实时影响个人积分榜排名；初赛倒计时结束后，按个人积分榜前 50 名生成复赛候选名单。</p><div class="progress-row"><span>当前积分</span><div class="tiny-progress"><span style="width:68%"></span></div><b>1,280</b></div><div class="progress-row"><span>当前排名</span><div class="tiny-progress"><span style="width:64%"></span></div><b>第 68 名</b></div></div>${heading('任务完成提示')}<div class="task-tip">已完成：安全生产学习课程、第一类闯关任务。建议优先完成今日签到和学后答题，持续提升个人积分排名。</div>${heading('后续赛段')}<div class="stage-switch"><button class="disabled" onclick="showToast('当前赛段暂未开启，请等待晋级结果公布。')"><b>🔒 复赛未开启</b><span>初赛结束后，排名进入晋级范围的用户可解锁复赛任务。</span></button><button class="disabled" onclick="showToast('当前赛段暂未开启，请等待晋级结果公布。')"><b>🔒 决赛未开启</b><span>复赛结束后，排名进入晋级范围的用户可解锁决赛任务。</span></button></div></div>${tabs()}`}
  function rankboard(){return `${top('积分榜','积分决定排名，排名决定赛段晋级')}<div class="h5-content"><section class="rank-summary-v4"><small>当前赛段 · 初赛阶段</small><h2>1,280 分</h2><span>个人积分持续累计，排名实时变化</span><div class="rank-info"><div><span>当前排名</span><b>第 68 名</b></div><div><span>晋级线</span><b>第 50 名</b></div><div><span>距离晋级线</span><b>还差 18 名</b></div><div><span>赛段倒计时</span><b>03 天 12 小时</b></div></div></section><div class="rank-rule-lite">晋级规则：初赛结束后按个人积分排名，前 50 名晋级复赛。积分仍会影响排名，但不存在固定积分晋级门槛。</div>${heading('榜单')}<div class="rank-tabs"><button class="active">个人榜</button><button>单位榜</button><button>赛段榜</button></div><div class="rank-table-head"><span>排名</span><span>参赛人员 / 单位</span><span>积分</span></div>${[['🥇','王晓磊','千铝工投 · 电解一车间','2,680'],['🥈','李雯','绿色铝业 · 动力保障部','2,560'],['🥉','赵勇','千铝工投 · 铸造车间','2,440'],['4','陈志远','华东铝业 · 电解二车间','2,320'],['5','刘子豪','千铝工投 · 阳极组装车间','2,150']].map(x=>`<div class="rank-row"><div class="rank-num">${x[0]}</div><div class="rank-avatar">${x[1][0]}</div><div><b>${x[1]}</b><small>${x[2]}</small></div><strong>${x[3]}</strong></div>`).join('')}</div>${tabs()}`}
  window.h5Go=function(page){if(page==='discover'||page==='tasks'||page==='rankboard'){const root=document.getElementById('competitionH5');root.innerHTML=page==='discover'?discover():page==='tasks'?tasks():rankboard();root.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===page));window.scrollTo(0,0);return}previousGo(page)};
})();
